    i9: "प्रत्येक साइन-इन: केव्हा, नेटवर्कचा पत्ता आणि ब्राउझर किंवा ॲपची आवृत्ती. साइन-इन दुवे आणि कोड, जे एकदाच चालतात.",
    i10: "कोणी काय केले आणि कोणत्या नेटवर्क पत्त्यावरून, याची ऑडिट नोंद, ज्यात सुरक्षा अहवाल आणि ॲपमधून पाठवलेले समस्या किंवा क्रॅश अहवाल येतात.",
    i11: "पसंती: भाषा, रूप, सूचनांची माध्यमे आणि शांत तास.",
    s3Title: "कोण पाहू शकते",
    s3a: "शाळेचा कर्मचारीवर्ग शाळेचे विद्यार्थी पाहतो; शिक्षक फक्त ते विद्यार्थी पाहतो ज्यांच्या वर्गाला तो शिकवतो. कार्यालय संपूर्ण निर्देशिका पाहते.",
