    s3c: "विद्यार्थी स्वतःची नोंद पाहतो. वर्गमित्रांना शिक्षकाने मंजूर केलेल्या बुलेटिन पोस्टवर नाव आणि अवतार दिसतो, आणखी काही नाही.",
    s3d: "शाळेबाहेरचे कोणीही विद्यार्थ्याचा डेटा पाहत नाही. बाहेरील मार्गदर्शक विद्यार्थ्याशी तेव्हाच संदेश करतो जेव्हा पालकाने संमती दिली असते, आणि स्पर्धेतील प्रवेशिकाही त्याच संमतीनेच शाळेबाहेर जाते.",
    s4Title: "EduLink काय करत नाही",
    s4a: "जाहिराती नाहीत, ॲनालिटिक्स नाही, ट्रॅकिंग नाही, वर्तनाचे प्रोफाइलिंग नाही, आणि दुसऱ्या कोणाच्याही हेतूसाठी डेटा विकला किंवा वाटला जात नाही.",
    s4b: "स्थान नाही, संपर्क नाहीत, जाहिरात ओळखक्रमांक नाही. अपलोड करताना छायाचित्रांमधून स्थान आणि कॅमेऱ्याचा तपशील काढून टाकला जातो; व्हिडिओ जसे रेकॉर्ड झाले तसेच वाटले जातात.",
